namespace Taruck.CharacterCreation
{
    internal static class CharacterWizardSpellText
    {
        internal static string Effect(RulesEdition edition, string name)
        {
            bool modern = edition == RulesEdition.Rules2024;
            switch (name)
            {
                case "Acid Splash": return modern
                    ? "Істоти у сфері радіусом 5 футів роблять ряткидок Спритності або отримують 1к6 кислотної шкоди."
                    : "Одна істота або дві в межах 5 футів одна від одної роблять ряткидок Спритності або отримують 1к6 кислотної шкоди.";
                case "Chill Touch": return modern
                    ? "Ближня атака заклинанням: 1к10 некротичної шкоди; ціль не відновлює ОЗ до кінця твого наступного ходу."
                    : "Далекобійна атака заклинанням: 1к8 некротичної шкоди; ціль не відновлює ОЗ до початку твого наступного ходу. Нежить також має заваду на атаки по тобі до кінця твого наступного ходу.";
                case "Fire Bolt": return "Далекобійна атака заклинанням: 1к10 вогняної шкоди. Горючий предмет, якого ніхто не носить, спалахує.";
                case "Sorcerous Burst": return "Далекобійна атака заклинанням: 1к8 кислоти, холоду, вогню, блискавки, отрути, психічної або громової шкоди. На 8 докидай ще к8; максимум додаткових кісток дорівнює модифікатору Харизми.";
                case "Mind Sliver": return "Ряткидок Інтелекту або 1к6 психічної шкоди й штраф 1к4 до наступного ряткидка до кінця твого наступного ходу.";
                case "Ray of Frost": return "Далекобійна атака заклинанням: 1к8 холодової шкоди й зменшення швидкості на 10 футів до початку твого наступного ходу.";
                case "Shocking Grasp": return modern
                    ? "Ближня атака заклинанням: 1к8 блискавичної шкоди; ціль не може робити провоковані атаки до початку свого наступного ходу."
                    : "Ближня атака заклинанням: 1к8 блискавичної шкоди; ціль не має реакцій до початку свого наступного ходу. Атака з перевагою проти металевого обладунку.";
                case "Chromatic Orb": return modern
                    ? "Далекобійна атака заклинанням: 3к8 кислоти, холоду, вогню, блискавки, отрути або грому. Два однакові результати к8 дозволяють ще одну атаку по іншій цілі в межах 30 футів. Потрібен діамант за 50 зм."
                    : "Далекобійна атака заклинанням: 3к8 кислоти, холоду, вогню, блискавки, отрути або грому на вибір. Потрібен діамант за 50 зм.";
                case "Color Spray": return modern ? "" : "Кинь 6к10: сума визначає запас ОЗ істот у конусі 15 футів, починаючи з найменших поточних ОЗ. Уражені Засліплені до кінця твого наступного ходу.";
                case "Expeditious Retreat": return "Здійсни Ривок при накладанні; до завершення заклинання можна робити Ривок бонусною дією.";
                case "False Life": return modern ? "Отримуєш 2к4 + 4 тимчасових ОЗ." : "Отримуєш 1к4 + 4 тимчасових ОЗ.";
                case "Find Familiar": return modern
                    ? "Закликає духа-фамільяра у формі звіра, який не атакує. Телепатія до 100 футів; бонусною дією можна бачити його очима, а реакцією він передає твої заклинання дотиком. Матеріали за 10 зм витрачаються."
                    : "Закликає духа-фамільяра у формі звіра, який не атакує. Телепатія до 100 футів; дією можна бачити його очима, а реакцією він передає твої заклинання дотиком. Матеріали за 10 зм витрачаються.";
                case "Grease": return "Квадрат 10 футів стає складною місцевістю. При появі, вході або завершенні ходу в ньому ряткидок Спритності або падіння долілиць.";
                case "Mage Armor": return "Для істоти без обладунку базовий КО стає 13 + модифікатор Спритності. Надягання обладунку завершує ефект.";
                case "Magic Missile": return "Три снаряди автоматично влучають у видимі цілі. Кожен завдає 1к4 + 1 силової шкоди; цілі можна розподілити.";
                case "Ray of Sickness": return modern
                    ? "Далекобійна атака заклинанням: 2к8 отруйної шкоди та стан Отруєний до кінця твого наступного ходу."
                    : "Далекобійна атака заклинанням: 2к8 отруйної шкоди; ряткидок Статури або стан Отруєний до кінця твого наступного ходу.";
                case "Shield": return "Реакція на влучання або Магічні снаряди: +5 КО до початку твого наступного ходу, включно з атакою-тригером; Магічні снаряди не завдають шкоди.";
                case "Tenser's Floating Disk": return "Диск несе до 500 фунтів на висоті 3 фути й слідує за тобою на відстані 20 футів. Не долає перепади висоти 10 футів; зникає при віддаленні понад 100 футів.";
                case "Witch Bolt": return modern
                    ? "Далекобійна атака заклинанням: 2к12 блискавичної шкоди. Наступними ходами бонусною дією завдавай 1к12 автоматично, навіть після першого промаху. Віддалення за дальність або повне укриття завершує ефект."
                    : "Далекобійна атака заклинанням: 1к12 блискавичної шкоди. Наступними ходами дією завдавай 1к12 автоматично; інша дія, віддалення за дальність чи повне укриття завершує ефект.";
                default: return "";
            }
        }
    }
}
